const rows = $input.all();

return rows.filter(item => {
    return String(item.json.Check_Exists || '').trim() === 'Chưa có';
});

const items = $input.all();

const getField = (obj, fieldName) => {
  if (!obj) return "";
  if (obj[fieldName] !== undefined && obj[fieldName] !== null) return obj[fieldName];
  const actualKey = Object.keys(obj).find(key => key.trim() === fieldName.trim());
  return actualKey !== undefined ? obj[actualKey] : "";
};

const normalize = value => String(value ?? "")
  .normalize("NFD").replace(/[\u0300-\u036f]/g, "")
  .toLowerCase().replace(/[^a-z0-9]+/g, " ").trim().replace(/\s+/g, " ");

const splitSkills = value => String(value ?? "").split(",").map(s => s.trim()).filter(Boolean);

// Chỉ ghép CV có Check_Exists = "Chưa có" với công việc tương ứng.
const matchingItems = items.filter(item => {
  const d = item.json || {};

  const check = String(getField(d, "Check_Exists") || "").trim();
  const jobId = String(getField(d, "job_id") || "").trim();
  const title = String(getField(d, "job_title") || "").trim();

  return check === "Chưa có" && !!jobId && !!title;
});

// Loại trùng theo email + job_id trong cùng lần chạy.
const seen = new Set();
const uniqueItems = matchingItems.filter(item => {
  const d = item.json || {};
  const email = normalize(getField(d, "Email") || getField(d, "candidate_email"));
  const jobId = String(getField(d, "job_id") || "").trim();
  const key = `${email}|${jobId}`;
  if (seen.has(key)) return false;
  seen.add(key);
  return true;
});

return uniqueItems.map((item, index) => {
  const d = item.json || {};
  const candidateName = getField(d, "Họ và tên") || getField(d, "candidate_name");
  const candidateEmail = getField(d, "Email") || getField(d, "candidate_email");
  const skillsText = getField(d, "Kỹ năng") || getField(d, "candidate_skills");
  const experienceText = getField(d, "Kinh nghiệm") || getField(d, "candidate_experience");
  const jobId = String(getField(d, "job_id") || "").trim();
  const jobTitle = getField(d, "job_title");
  const appliedPosition = getField(d, "Vị trí ứng tuyển") || getField(d, "applied_position") || jobTitle;
  const requiredSkills = splitSkills(getField(d, "required_skills"));
  const preferredSkills = splitSkills(getField(d, "preferred_skills"));
  const candidateText = normalize(`${skillsText} ${experienceText}`);

  const matchedRequired = requiredSkills.filter(s => candidateText.includes(normalize(s)));
  const missingRequired = requiredSkills.filter(s => !candidateText.includes(normalize(s)));
  const matchedPreferred = preferredSkills.filter(s => candidateText.includes(normalize(s)));
  const missingPreferred = preferredSkills.filter(s => !candidateText.includes(normalize(s)));

  const position = normalize(jobTitle);
  const exp = normalize(experienceText);
  let keywords = [];
  if (position.includes("backend") || position.includes("developer")) {
    keywords = ["backend", "back end", "rest api", "restful api", "spring boot", "software developer"];
  } else if (position.includes("data analyst") || position.includes("phan tich du lieu")) {
    keywords = ["data analyst", "phan tich du lieu", "sql", "power bi", "tableau", "data analysis"];
  } else if (position.includes("marketing") || position.includes("truyen thong")) {
    keywords = ["marketing", "truyen thong", "content", "social media", "copywriting", "digital marketing"];
  }
  const hasRelevantExperience = keywords.some(k => exp.includes(normalize(k)));
  const requiredRate = requiredSkills.length ? matchedRequired.length / requiredSkills.length : 0;
  const preferredRate = preferredSkills.length ? matchedPreferred.length / preferredSkills.length : 0;
  const score = Math.round((requiredRate * 0.7 + preferredRate * 0.2 + (hasRelevantExperience ? 0.1 : 0)) * 100) / 10;

  let recommendation = "Low Match";
  if (score >= 8) recommendation = "Strong Match";
  else if (score >= 6) recommendation = "Potential Match";

  const reasons = [
    `Đáp ứng ${matchedRequired.length}/${requiredSkills.length} kỹ năng bắt buộc.`,
    `Đáp ứng ${matchedPreferred.length}/${preferredSkills.length} kỹ năng ưu tiên.`,
    hasRelevantExperience ? "Tìm thấy từ khóa kinh nghiệm liên quan đến vị trí." : "Chưa tìm thấy từ khóa kinh nghiệm liên quan rõ ràng."
  ];
  if (missingRequired.length) reasons.push(`Kỹ năng bắt buộc cần kiểm tra thêm: ${missingRequired.join(", ")}.`);

  return {
    json: {
      application_id: `${candidateEmail}|${jobId}`,
      "Họ và tên ứng viên": candidateName,
      "Email ứng viên": candidateEmail,
      "Vị trí ứng tuyển": appliedPosition,
      "Mã tin tuyển dụng": jobId,
      "Tên vị trí tuyển dụng": jobTitle,
      "Điểm phù hợp": score,
      "Đề xuất đánh giá": recommendation,
      "Kỹ năng bắt buộc phù hợp": matchedRequired.join(", "),
      "Kỹ năng bắt buộc còn thiếu": missingRequired.join(", "),
      "Kỹ năng ưu tiên phù hợp": matchedPreferred.join(", "),
      "Kỹ năng ưu tiên còn thiếu": missingPreferred.join(", "),
      "Kinh nghiệm liên quan": hasRelevantExperience,
      "Lý do đánh giá": reasons.join(" "),
      "Phương pháp đánh giá": "Đối chiếu từ khóa theo quy tắc",
      "Thời gian đánh giá": new Date().toISOString(),
      "Trạng thái gửi email cho HR": "Chưa gửi",
      "Quyết định của HR": "Pending Review",
      "Ngày phỏng vấn": "",
      "Giờ phỏng vấn": "",
      "Trạng thái gửi email cho ứng viên": "Chưa gửi"
    },
    pairedItem: { item: index }
  };
});

